import functools,http.server,json,pathlib,threading,subprocess
from playwright.sync_api import sync_playwright,expect
root=pathlib.Path.cwd();server=http.server.ThreadingHTTPServer(('127.0.0.1',4188),functools.partial(http.server.SimpleHTTPRequestHandler,directory=str(root/'out')));threading.Thread(target=server.serve_forever,daemon=True).start()
try:
 with sync_playwright() as p:
  b=p.chromium.launch(executable_path='/opt/google/chrome/chrome',headless=True,args=['--no-sandbox'])
  for lang in ['en','ar']:
   page=b.new_page(viewport={'width':900,'height':1100},reduced_motion='reduce');page.add_init_script('window.__prints=0;window.print=()=>window.__prints++;');t=json.load(open('src/i18n/locales/'+lang+'.json'));page.goto('http://127.0.0.1:4188/?lang='+lang+'#resources');page.get_by_text('Practice Worksheet & Answer Key',exact=True).locator('..').locator('..').get_by_role('button',name=t['rs.preview']+':',exact=False).click();page.get_by_role('button',name=t['rs.print'],exact=True).click();assert page.evaluate('window.__prints')==1;page.emulate_media(media='print');expect(page.get_by_text('Future Perfect Master Summary',exact=True)).not_to_be_visible();pre=page.locator('#resource-print-sheet pre');expect(pre).to_be_visible();assert pre.evaluate('(e)=>getComputedStyle(e).backgroundColor')=='rgb(255, 255, 255)';assert pre.evaluate('(e)=>getComputedStyle(e).color')=='rgb(17, 17, 17)';assert page.evaluate('getComputedStyle(document.documentElement).backgroundColor')=='rgb(255, 255, 255)';assert page.evaluate('getComputedStyle(document.documentElement).colorScheme')=='light';path='/downloads/resource-print-'+lang+'.pdf';page.pdf(path=path,format='A4',print_background=True,margin={'top':'15mm','bottom':'15mm','left':'15mm','right':'15mm'});text=subprocess.check_output(['pdftotext',path,'-'],text=True);assert '10. How many books' in text;assert 'Part C' in text;assert 'Check your own work' in text;assert '50 Most Essential' not in text;assert 'FORMAL WRITING TEMPLATES' not in text;page.emulate_media(media='screen');expect(page.get_by_text('Future Perfect Master Summary',exact=True)).to_be_visible();page.close();print(lang,'Next print button nativecall,selecteddocumentonly,whitepaperblacktext,full tasks/keys/model inPDF,screen restored PASS')
  b.close()
finally:server.shutdown();server.server_close()
